import itertools

def max_independent_set_size(n, edges):
    # adjacency matrix
    adj = [[False]*n for _ in range(n)]
    for u,v in edges:
        adj[u][v] = adj[v][u] = True
    max_size = 0
    for r in range(n+1):
        for subset in itertools.combinations(range(n), r):
            ok = True
            for i in range(r):
                for j in range(i+1, r):
                    if adj[subset[i]][subset[j]]:
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                max_size = max(max_size, r)
    return max_size

def vertex_connectivity(n, edges):
    # simple brute force for n=9
    from itertools import combinations
    adj = [[False]*n for _ in range(n)]
    for u,v in edges:
        adj[u][v] = adj[v][u] = True
    # check if graph is connected
    def is_connected(exclude=set()):
        start = None
        for i in range(n):
            if i not in exclude:
                start = i
                break
        if start is None:
            return False
        stack = [start]
        visited = set([start])
        while stack:
            u = stack.pop()
            for v in range(n):
                if v not in exclude and adj[u][v] and v not in visited:
                    visited.add(v)
                    stack.append(v)
        return len(visited) == n - len(exclude)

    if not is_connected():
        return 0
    for k in range(1, n):
        for cut in combinations(range(n), k):
            if not is_connected(set(cut)):
                return k
    return n-1

